mapper.select:
select * from operation
 where resource_type = #{resourceType}
   and resource_id = #{resourceId}
 order by created_at desc, id

select * from operation
 where automation_session_id = #{sessionId}
 order by created_at asc, id

select * from operation


        status = #{status}


order by updated_at desc, id
limit #{limit}

mapper.update:
update operation
   set risk_level = #{riskLevel},
       impact_json = #{impactJson},
       updated_at = #{updatedAt}
 where id = #{id}

update operation
   set agent_command_id = #{agentCommandId},
       updated_at = #{updatedAt}
 where id = #{id}

mapper.insert:
insert into operation_event(
    id, operation_id, sequence, event_type, actor, detail_json, occurred_at
) values (
    #{id}, #{operationId}, #{sequence}, #{eventType}, #{actor}, #{detailJson}, #{occurredAt}
)
